/** Every art name the app can draw. A typo is a type error, not a blank box. */
export type ArtName = keyof typeof ART;

export function getArtModule(name: ArtName): number {
  return ART[name];
}

/** For tests and tooling that need to walk the whole set. */
export const ART_NAMES = Object.keys(ART) as ArtName[];
